import java.util.*;

class TreeMapLite<K extends Comparable<K>, V> {
    private class Node {
        K key;
        V value;
        Node left, right;
        Node(K key, V value) { this.key = key; this.value = value; }
    }

    private Node root;
    private int size;

    void put(K key, V value) {
        Objects.requireNonNull(key);
        root = put(root, key, value);
    }

    private Node put(Node n, K key, V value) {
        if (n == null) { size++; return new Node(key, value); }
        int c = key.compareTo(n.key);
        if (c < 0) n.left = put(n.left, key, value);
        else if (c > 0) n.right = put(n.right, key, value);
        else n.value = value;
        return n;
    }

    private Node find(K key) {
        Objects.requireNonNull(key);
        Node n = root;
        while (n != null) {
            int c = key.compareTo(n.key);
            if (c == 0) return n;
            n = c < 0 ? n.left : n.right;
        }
        return null;
    }

    V get(K key) {
        Node n = find(key);
        return n == null ? null : n.value;
    }

    boolean containsKey(K key) { return find(key) != null; }

    boolean remove(K key) {
        if (!containsKey(key)) return false;
        root = remove(root, key);
        size--;
        return true;
    }

    private Node remove(Node n, K key) {
        int c = key.compareTo(n.key);
        if (c < 0) { n.left = remove(n.left, key); return n; }
        if (c > 0) { n.right = remove(n.right, key); return n; }
        if (n.left == null) return n.right;
        if (n.right == null) return n.left;
        Node s = n.right;
        while (s.left != null) s = s.left;
        n.key = s.key;
        n.value = s.value;
        n.right = remove(n.right, s.key);
        return n;
    }

    int size() { return size; }

    int height() { return height(root); }

    private int height(Node n) { return n == null ? -1 : 1 + Math.max(height(n.left), height(n.right)); }

    List<K> keys() {
        List<K> out = new ArrayList<>();
        inOrder(root, out);
        return out;
    }

    private void inOrder(Node n, List<K> out) {
        if (n == null) return;
        inOrder(n.left, out);
        out.add(n.key);
        inOrder(n.right, out);
    }

    K floorKey(K key) {
        Objects.requireNonNull(key);
        K best = null;
        Node n = root;
        while (n != null) {
            int c = key.compareTo(n.key);
            if (c == 0) return n.key;
            if (c < 0) n = n.left;
            else { best = n.key; n = n.right; }
        }
        return best;
    }

    int countBetween(K lo, K hi) { return countBetween(root, lo, hi); }

    private int countBetween(Node n, K lo, K hi) {
        if (n == null) return 0;
        if (n.key.compareTo(lo) < 0) return countBetween(n.right, lo, hi);
        if (n.key.compareTo(hi) > 0) return countBetween(n.left, lo, hi);
        return 1 + countBetween(n.left, lo, hi) + countBetween(n.right, lo, hi);
    }
}

