Supplier<TreeMapLite<Integer, String>> sample = () -> {
    TreeMapLite<Integer, String> t = new TreeMapLite<>();
    for (int k : new int[] {50, 30, 70, 20, 40, 60, 80, 35, 45}) t.put(k, "v" + k);
    return t;
};

test("put, get and replace", () -> {
    TreeMapLite<Integer, String> t = sample.get();
    checkEq(t.size(), 9);
    checkEq(t.get(40), "v40");
    checkEq(t.get(41), null);
    t.put(40, "forty");
    checkEq(t.get(40), "forty");
    checkEq(t.size(), 9);
    checkEq(t.keys(), List.of(20, 30, 35, 40, 45, 50, 60, 70, 80));
    checkEq(t.height(), 3);
    checkEq(new TreeMapLite<String, Integer>().height(), -1);
    checkThrows(NullPointerException.class, () -> t.put(null, "x"));
});

test("removing", () -> {
    TreeMapLite<Integer, String> t = sample.get();
    checkEq(t.remove(20), true);
    checkEq(t.remove(30), true);
    checkEq(t.remove(50), true);
    checkEq(t.remove(99), false);
    checkEq(t.keys(), List.of(35, 40, 45, 60, 70, 80));
    checkEq(t.size(), 6);
    checkEq(t.get(45), "v45");
    for (int k : List.of(35, 40, 45, 60, 70, 80)) t.remove(k);
    checkEq(t.size(), 0);
    checkEq(t.keys(), List.of());
});

test("floor and ranges", () -> {
    TreeMapLite<Integer, String> t = sample.get();
    checkEq(t.floorKey(44), 40);
    checkEq(t.floorKey(45), 45);
    checkEq(t.floorKey(10), null);
    checkEq(t.floorKey(1000), 80);
    checkEq(t.countBetween(33, 62), 5);
    checkEq(t.countBetween(81, 90), 0);
    checkEq(t.countBetween(0, 100), 9);
});

test("works with strings", () -> {
    TreeMapLite<String, Integer> words = new TreeMapLite<>();
    for (String w : "the quick brown fox jumps over the lazy dog".split(" ")) {
        Integer old = words.get(w);
        words.put(w, old == null ? 1 : old + 1);
    }
    checkEq(words.get("the"), 2);
    checkEq(words.keys().get(0), "brown");
    checkEq(words.floorKey("m"), "lazy");
});

